const wordReferenceLanguages = [
  // "es",
  // "fr",
  // "it",
  // "de",
  // "pt",
  // "pl",
  // "ro",
  // "cs",
  // "el",
  // "tr",
  // "ja",
  // "zh",
  // "ru",
];

_.each(map, (lang, code) => {
  if (
    !lang.frequencies ||
    lang.noWordBoundaries ||
    lang.direction === "RTL" ||
    (!_.contains(wordReferenceLanguages, code) && !lang.dictionaryURL)
  ) {
    lang.beta = true;
  }
});

delete map.en.beta;

const wordReferenceCode = (code) => {
  if (code === "el") {
    return "gr";
  } else if (code === "cs") {
    return "cz";
  }
  return code;
};

export const list = utils.sortBy(
  _.map(map, (info, code) => _.extend(info, { code: code })),
  { english: 1 }
);

export const learningMap = {};
_.each(map, (info, code) => {
  if (!info.firstLanguageOnly) {
    learningMap[code] = info;
  }
});

export const learningList = utils.sortBy(
  _.filter(list, (info) => !info.firstLanguageOnly),
  { english: 1 }
);

