export const languageSupportsChat = (code) => {
  const language = map[code];
  return language && !language.noWordBoundaries && language.direction !== "RTL";
};

/**
 * Returns the CJK font region for a language, or undefined if not a CJK language.
 * @param {string} code - The language code
 * @returns {"JP" | "SC" | "TC" | "HK" | "KR" | undefined}
 */
export const getCJKFontRegion = (code) => {
  const language = map[code];
  return language?.cjkFontRegion;
};

const getWordReferenceCodes = (source, target) => {
  const result = {};

  if (wordReferenceLanguages.indexOf(source) === -1 && source !== "en") {
    // can't do anything
    return {};
  }

  if (source !== "en" && target !== "en") {
    target = "en";
    result.targetLanguageCode = "en";
  } else if (wordReferenceLanguages.indexOf(target) !== -1 || target === "en") {
    result.targetLanguageCode = target;
  } else {
    return {};
  }

  result.source = wordReferenceCode(source);
  result.target = wordReferenceCode(target);

  return result;
};

const wiktionaryURLTemplate = (firstLanguage, learningLanguage) =>
  `https://${firstLanguage}.m.wiktionary.org/wiki/{{query}}${
    learningLanguage ? `#${map[learningLanguage].english}` : ""
  }`;

// gets a template where {{query}} needs to be replaced with the word/phrase to lookup to be
// complete
export const getEmbeddedDictionaryTemplate = (source, target, user) => {
  const result = {};
  const wordReferenceLanguageCodes = getWordReferenceCodes(source, target);
  const customDictionaries = user && user.state.value.customDictionaries;
  let urlTarget;
  let urlSource;

  if (source === target) {
    // monolingual mode
    if (customDictionaries && customDictionaries[source + "-mono"]) {
      result.urlTemplate = customDictionaries[source + "-mono"];
    } else if (map[source].monolingualDictionaryURL) {
      result.urlTemplate = map[source].monolingualDictionaryURL;
    } else if (map[source].wiktionary) {
      result.urlTemplate = wiktionaryURLTemplate(source);
    }
  } else if (customDictionaries && customDictionaries[source]) {
    result.urlTemplate = customDictionaries[source];
  } else if (source === "es" && target === "en") {
    result.urlTemplate = "https://dict.readlang.com/spanish-english/{{query}}";
    result.target = target;
  } else if (map[source].dictionaryURL) {
    urlTarget = map[source].dictionaryCodes[target];
    urlSource = map[source].dictionaryCodes[source];

    if (urlTarget) {
      result.target = target;
    } else {
      const pair = _.first(_.pairs(map[source].dictionaryCodes));

      result.target = pair[0];
      urlTarget = pair[1];
    }

    result.urlTemplate = map[source].dictionaryURL
      .replace(/{{source}}/g, encodeURIComponent(urlSource))
      .replace(/{{target}}/g, encodeURIComponent(urlTarget));
  } else if (map[target].dictionaryURL) {
    urlTarget = map[target].dictionaryCodes[target];
    urlSource = map[target].dictionaryCodes[source];

    if (urlSource) {
      result.target = target;

      result.urlTemplate = map[target].dictionaryURL
        .replace(/{{source}}/g, encodeURIComponent(urlSource))
        .replace(/{{target}}/g, encodeURIComponent(urlTarget));
    }
  } else if (wordReferenceLanguageCodes.source) {
    result.urlTemplate =
      "https://www.wordreference.com/" +
      wordReferenceLanguageCodes.source +
      wordReferenceLanguageCodes.target +
      "/{{query}}";
    result.target = wordReferenceLanguageCodes.targetLanguageCode;
  } else if (map[target].wiktionary) {
    result.urlTemplate = wiktionaryURLTemplate(target, source);
    result.target = target;
  }

  return result;
};

export const getEmbeddedDictionary = (source, target, query, context, user) => {
  /** @type {any} */
  const result = getEmbeddedDictionaryTemplate(source, target, user);

  if (result.urlTemplate) {
    result.URL = result.urlTemplate
      .replace(/{{query}}/g, encodeURIComponent(query))
      .replace(/{{context}}/g, encodeURIComponent(context));

    // sandboxed iframe to prevent focus stealing
    result.html =
      '<iframe sandbox="allow-forms allow-scripts allow-same-origin" id=wordReferenceIFrame src="' +
      result.URL +
      '"></iframe>';

    if (typeof window !== "undefined") {
      if (window.location && window.location.protocol === "https:") {
        if (
          /^http:/.test(result.URL) &&
          // @ts-ignore
          !window.READLANG.httpsWarningDismissed
        ) {
          result.html =
            '<div class="dictionaryWarning">' +
            '<div class="closeButton" onclick="$(this).parent().remove();window.READLANG.httpsWarningDismissed=true;">&nbsp;x&nbsp;</div>' +
            "<p>If the dictionary doesn't appear, it's probably because your browser is preventing " +
            "unsecure content appearing on this page.</p>" +
            '<p>Either click the "Open in new window" button above' +
            ' or allow the "unsafe" dictionary content as follows...' +
            "</p>" +
            "<h3>Chrome:</h3>" +
            '<img src="/content/chromeMixedContent.png"/>' +
            "<h3>Firefox:</h3>" +
            '<img src="/content/firefoxMixedContent.png"/>' +
            "</div>" +
            result.html;
        }
      }
    }
  } else {
    result.html =
      "<p>Readlang doesn't have a " +
      (source === target
        ? "monolingual dictionary for " + map[source].english
        : "dictionary for " +
          map[source].english +
          " to " +
          map[target].english) +
      ".</p>" +
      '<p><strong>Add a dictionary yourself</strong> by following these instructions: <a target="_blank" href="https://forum.readlang.com/t/change-the-dictionary/52">Add a custom dictionary</a>.</p>';
  }

  return result;
};

const flagLanguageCodes = [
  "es",
  "de",
  "en",
  "fr",
  "it",
  "ru",
  "nl",
  "pl",
  "pt",
  "ko",
  "sv",
  "el",
  "no",
];

export const isLowResource = (code) => map[code]?.lowResource ?? false;

export const flagList = _.map(flagLanguageCodes, (code) => ({
  ...map[code],
  code,
}));
