import $ from "jquery";
import * as _ from "underscore";

type JQueryElement = JQuery<HTMLElement>;

type PopoverEntry = {
  bubble: JQueryElement;
  span: JQueryElement;
};

type Config = {
  dismissSpan: (span: JQueryElement) => void;
  getPopoverKey: (span: JQueryElement) => string;
  getTranslatedSpans: () => JQuery<HTMLElement>;
  isPopoverStyle: () => boolean;
};

let config: Config | null = null;
let popoverLayer: JQueryElement | null = null;
let popoverAnimationFrame: number | null = null;
let popoverListenersBound = false;
let popoverEntries: { [key: string]: PopoverEntry } = {};

const ensurePopoverLayer = () => {
  if (popoverLayer?.length) {
    return popoverLayer;
  }

  popoverLayer = $("#readerPopoverLayer");
  if (popoverLayer.length === 0) {
    popoverLayer = $(
      '<div id="readerPopoverLayer" class="readerPopoverLayer"/>'
    );
    $("body").append(popoverLayer);
  }

  return popoverLayer;
};

const removePopoverEntry = (key: string) => {
  const entry = popoverEntries[key];
  if (!entry) {
    return;
  }

  entry.bubble.remove();
  delete popoverEntries[key];
};

const getPopoverViewportRect = () => {
  const viewport = document.getElementById("pageTextViewport");
  return (
    viewport?.getBoundingClientRect() ?? {
      top: 0,
      left: 0,
      right: window.innerWidth,
      bottom: window.innerHeight,
      width: window.innerWidth,
      height: window.innerHeight,
    }
  );
};

const updatePopoverLayerBounds = () => {
  const layer = ensurePopoverLayer();
  const mediaPlayer = $("#mediaPlayer:visible");
  const clipTop =
    mediaPlayer.length > 0 && mediaPlayer.height() > 0
      ? mediaPlayer[0].getBoundingClientRect().bottom
      : 0;

  layer.css({
    top: clipTop + "px",
    left: "0px",
    right: "0px",
    bottom: "0px",
  });
};

type Rect = {
  top: number;
  bottom: number;
  left: number;
  right: number;
  width: number;
  height: number;
};

export const computePopoverPosition = (
  spanRect: Rect,
  clientRects: ArrayLike<Rect>,
  bubbleRect: Pick<Rect, "width" | "height">,
  windowWidth: number
): { left: number; top: number; arrowLeft: number; placeBelow: boolean } => {
  const offset = 6;
  const margin = 8;
  const arrowMinMargin = 12;
  const placeBelow = spanRect.top - bubbleRect.height - offset < 0;

  const targetRect =
    clientRects.length <= 1
      ? spanRect
      : placeBelow
        ? clientRects[clientRects.length - 1]
        : clientRects[0];

  const targetCenter = targetRect.left + targetRect.width / 2;
  let left = targetCenter - bubbleRect.width / 2;
  left = Math.max(margin, left);
  left = Math.min(windowWidth - bubbleRect.width - margin, left);

  const top = placeBelow
    ? targetRect.bottom + offset
    : targetRect.top - bubbleRect.height - offset;

  const arrowLeft = Math.max(
    arrowMinMargin,
    Math.min(targetCenter - left, bubbleRect.width - arrowMinMargin)
  );

  return { left, top, arrowLeft, placeBelow };
};

const repositionPopoverForKey = (key: string) => {
  const entry = popoverEntries[key];
  if (!entry) {
    return;
  }

  const spanElement = entry.span?.[0];
  if (
    !spanElement ||
    !document.body.contains(spanElement) ||
    !entry.span.hasClass("translated")
  ) {
    removePopoverEntry(key);
    return;
  }

  const spanRect = spanElement.getBoundingClientRect();
  const viewportRect = getPopoverViewportRect();
  const layer = ensurePopoverLayer();
  const layerRect = layer[0].getBoundingClientRect();

  if (
    spanRect.bottom < viewportRect.top ||
    spanRect.top > viewportRect.bottom ||
    spanRect.right < viewportRect.left ||
    spanRect.left > viewportRect.right
  ) {
    entry.bubble.css("display", "none");
    return;
  }

  const bubble = entry.bubble;
  bubble.css({
    display: "block",
    left: "0px",
    top: "0px",
    visibility: "hidden",
  });

  const bubbleRect = bubble[0].getBoundingClientRect();
  const { left, top, arrowLeft, placeBelow } = computePopoverPosition(
    spanRect,
    spanElement.getClientRects(),
    bubbleRect,
    window.innerWidth
  );

  bubble[0].style.setProperty("--arrow-left", arrowLeft + "px");
  bubble.toggleClass("popoverBelow", placeBelow);
  bubble.css({
    left: left + "px",
    top: top - layerRect.top + "px",
    visibility: "visible",
  });
};

const bindPopoverListeners = () => {
  if (popoverListenersBound) {
    return;
  }

  $(window).on("resize.spanTranslatorPopover", scheduleRepositionPopovers);
  $(window).on("scroll.spanTranslatorPopover", scheduleRepositionPopovers);
  $(document).on(
    "click.spanTranslatorPopover",
    ".readerPopoverBubble",
    (event) => {
      event.stopPropagation();
      event.preventDefault();

      const key = $(event.currentTarget).attr("data-popover-key");
      if (!key) {
        return;
      }

      const entry = popoverEntries[key];
      if (!entry?.span?.length) {
        removePopoverEntry(key);
        return;
      }

      config?.dismissSpan(entry.span);
    }
  );
  popoverListenersBound = true;
};

export const setupPopoverLayer = (nextConfig: Config) => {
  config = nextConfig;
  popoverEntries = {};
  popoverLayer = $("#readerPopoverLayer");
  popoverLayer.empty();
  bindPopoverListeners();
};

export const removePopoverForSpan = (span: JQueryElement) => {
  if (!config) {
    return;
  }

  removePopoverEntry(config.getPopoverKey(span));
};

export const clearPopoverEntries = () => {
  _.each(_.keys(popoverEntries), (key) => {
    removePopoverEntry(key);
  });
};

export const showPopoverForSpan = (
  span: JQueryElement,
  schedulePosition = true
) => {
  if (!config) {
    return;
  }

  if (!config.isPopoverStyle()) {
    removePopoverForSpan(span);
    return;
  }

  const translationElement = span.find(".translation");
  if (translationElement.length === 0) {
    removePopoverForSpan(span);
    return;
  }

  const key = config.getPopoverKey(span);
  const layer = ensurePopoverLayer();
  let entry = popoverEntries[key];
  if (!entry) {
    const bubble = $('<div class="readerPopoverBubble"/>');
    layer.append(bubble);
    entry = {
      bubble,
      span,
    };
    popoverEntries[key] = entry;
  } else {
    entry.span = span;
  }

  entry.bubble.attr("data-popover-key", key);
  const translationStyles = window.getComputedStyle(translationElement[0]);
  entry.bubble.html(translationElement.html());
  entry.bubble.css({
    fontFamily: translationStyles.fontFamily,
    fontSize: translationStyles.fontSize,
    fontWeight: translationStyles.fontWeight,
    lineHeight: translationStyles.lineHeight,
  });
  if (schedulePosition) {
    scheduleRepositionPopovers();
  }
};

export const strikeThroughPopoverForSpan = (span: JQueryElement) => {
  if (!config) {
    return;
  }

  const entry = popoverEntries[config.getPopoverKey(span)];
  if (!entry) {
    return;
  }

  entry.bubble.css("text-decoration", "line-through");
};

export const scheduleRepositionPopovers = () => {
  if (!config || popoverAnimationFrame !== null) {
    return;
  }

  popoverAnimationFrame = window.requestAnimationFrame(() => {
    popoverAnimationFrame = null;

    if (!config?.isPopoverStyle()) {
      clearPopoverEntries();
      return;
    }

    updatePopoverLayerBounds();
    config.getTranslatedSpans().each((_index, element) => {
      showPopoverForSpan($(element), false);
    });

    _.each(_.keys(popoverEntries), (key) => {
      repositionPopoverForKey(key);
    });
  });
};

export const closePopoverLayer = () => {
  clearPopoverEntries();
};
