import $ from "jquery";

import * as deviceDetect from "deviceDetect";

// Popup Element
let _popupElement;

let hoveringOverPopup = false;
let onPopupUnhover;

const getPopupElement = () => {
  if (_popupElement) {
    return _popupElement;
  }
  _popupElement = $("<a>");
  _popupElement.hover(
    () => {
      hoveringOverPopup = true;
    },
    () => {
      hoveringOverPopup = false;
      if (onPopupUnhover) {
        onPopupUnhover();
        onPopupUnhover = undefined;
      }
    }
  );

  return _popupElement;
};

const createLinkPopup = (originalLink) => {
  const href = originalLink.attr("href");
  const title = originalLink.attr("title");

  const position = originalLink.offset();
  const height = originalLink.outerHeight();
  const width = originalLink.outerWidth();

  originalLink.removeAttr("title");

  const popupElement = getPopupElement();

  popupElement
    .html("Open link &#8594;")
    .addClass("readlang-link-popup")
    .attr("title", title)
    .attr("href", href)
    .css({
      position: "absolute",
      top: position.top + height,
      left: position.left + width / 2,
    });
};

let hideTimer;
let enabled = true;

const setEnabled = (_enabled) => {
  enabled = _enabled;
};

let $target;
let mouseMoveTimer;

const onMouseMove = () => {
  clearTimeout(mouseMoveTimer);
  mouseMoveTimer = setTimeout(showLink, 300);
};

var showLink = () => {
  clearTimeout(hideTimer);
  createLinkPopup($target);
  $("body").append(getPopupElement());
  getPopupElement().stop().css({ opacity: 1 }).show();
};

const hideLink = () => {
  clearTimeout(hideTimer);
  clearTimeout(mouseMoveTimer);
  getPopupElement().fadeOut();
  $target = undefined;
};

const onLinkUnhover = () => {
  clearTimeout(mouseMoveTimer);
  clearTimeout(hideTimer);
  hideTimer = setTimeout(() => {
    if (getPopupElement()) {
      if (hoveringOverPopup) {
        onPopupUnhover = hideLink;
      } else {
        hideLink();
      }
    }
  }, 500);
};

const setup = (element) => {
  // link pop-up
  element.find("a[href]").hover(
    (event) => {
      if (!enabled) {
        return;
      }

      if ($target) {
        $target.off("mousemove");
      }
      $target = $(event.currentTarget);

      if ($target.closest(".readlang-ignore").length > 0) {
        return;
      }

      clearTimeout(hideTimer);
      clearTimeout(mouseMoveTimer);
      mouseMoveTimer = setTimeout(showLink, 300);
      $target.mousemove(onMouseMove);
    },
    () => {
      if (!enabled) {
        return;
      }

      if ($target) {
        $target.off("mousemove");
        clearTimeout(mouseMoveTimer);
        onLinkUnhover();
      }
    }
  );

  if (deviceDetect.is("iOS") || deviceDetect.is("android")) {
    element.find("a[href]").each((index, link) => {
      const $link = $(link);
      if ($link.find("span[data-p]").length > 0) {
        $link.after(
          $("<a>")
            .html(" &#8594; ")
            .css({ color: "#080" })
            .attr("href", $link.attr("href"))
        );
      }
    });
  }
};

const updateLink = () => {
  if ($target) {
    createLinkPopup($target);
  }
};

export { setEnabled, setup, updateLink };
