import * as _ from "underscore";

import { letter as L, mark as M, notLetter } from "./unicodePatterns.js";

export const notWordRegExp = () => new RegExp(`[^’’${L}${M}]+`, "gu");

export const addPrePadding = (content, padding) => {
  const contentString = String(content);
  return (
    padding.substring(0, padding.length - contentString.length) + contentString
  );
};

export const elide = (string, maxLength) => {
  if (string.length > maxLength) {
    return string.substring(0, maxLength - 2) + "…";
  }
  return string;
};

export const regexpEscape = (input) =>
  input.replace(/[[\]/{}()*+?.\\^$|]/g, "\\$&");

export const stripDiacritics = (input) =>
  input.normalize("NFD").replace(/\p{Diacritic}/gu, "");

export const htmlEscape = (input) =>
  input.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");

export const simpleMarkupToHtml = (input) => {
  if (!input) {
    return "";
  }
  return (
    htmlEscape(input)
      // bold
      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
      // urls
      .replace(/https?:\/\/\S*/g, (url) => {
        // ignore trailing punctuation
        let after = "";
        while (
          url.length > 0 &&
          /[.,<>(){}\-;:'"[\]]/g.test(url[url.length - 1])
        ) {
          after += url[url.length - 1];
          url = url.substring(0, url.length - 1);
        }
        return '<a href="' + url + '">' + url + "</a>" + after;
      })
      // newlines
      .replace(/\n/g, "<br>")
  );
};

export const addCommasToNumber = (number) => {
  let string = String(number);
  const result = [];

  while (string.length > 0) {
    result.splice(
      0,
      0,
      string.slice(Math.max(string.length - 3, 0), string.length)
    );
    string = string.substring(0, Math.max(string.length - 3, 0));
  }

  return result.join(",");
};

export const getDomainFromUrl = (url) =>
  _.find(url.split("/"), (a) => a.length > 0 && !/:$/.test(a));

