export const normalizeString = (string, normalizeAccents) => {
  if (string.normalize) {
    string = string.normalize();
  }

  const characterMap = normalizeAccents
    ? {
        ...normalizedCharacterMap,
        ...accentsMap,
      }
    : normalizedCharacterMap;

  return string
    .split("")
    .map((character) => characterMap[character] ?? character)
    .join("");
};

// sorts an array in place, by an arbitrary number of sort keys
export const sortBy = (array, sortKeys) => {
  const result = _.clone(array);
  const keyPairs = _.pairs(sortKeys);

  result.sort((a, b) => {
    for (let i = 0; i < keyPairs.length; i++) {
      const key = keyPairs[i][0];
      const direction = keyPairs[i][1];

      if (!a[key] && b[key]) return direction;
      if (a[key] && !b[key]) return -direction;
      if (a[key] > b[key]) return direction;
      if (a[key] < b[key]) return -direction;
    }
    return 0;
  });

  return result;
};

// from http://en.wikibooks.org/wiki/Algorithm_Implementation/Strings/Levenshtein_distance#JavaScript
export const levenshteinDistance = (a, b) => {
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;

  const matrix = [];

  // increment along the first column of each row
  let i;
  for (i = 0; i <= b.length; i++) {
    matrix[i] = [i];
  }

  // increment each column in the first row
  let j;
  for (j = 0; j <= a.length; j++) {
    matrix[0][j] = j;
  }

  // Fill in the rest of the matrix
  for (i = 1; i <= b.length; i++) {
    for (j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) == a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1, // substitution
          Math.min(
            matrix[i][j - 1] + 1, // insertion
            matrix[i - 1][j] + 1
          )
        ); // deletion
      }
    }
  }

  return matrix[b.length][a.length];
};

export const childExists = (object, path) =>
  typeof valueFromPath(object, path) !== "undefined";

// returns undefined if path doesn't exist
export const valueFromPath = (object, path) => {
  if (!object) {
    return undefined;
  }

  let restOfObject = object;

  const exists = _.every(path.split("."), (key) => {
    if (restOfObject[key]) {
      restOfObject = restOfObject[key];
      return true;
    }
  });

  if (exists) {
    return restOfObject;
  }
};

export const toTitleCase = (input) =>
  input.replace(
    /(^|\W)(\w)/g,
    (_whole, space, letter) => space + letter.toUpperCase()
  );

/** @param {string[]} terms */
export const displayListOfTerms = (terms) =>
  terms
    .map((term, index) => {
      if (index === terms.length - 1) {
        return term;
      } else if (index === terms.length - 2) {
        return `${term} and`;
      } else {
        return `${term},`;
      }
    })
    .join(" ");

export const sleep = async (duration) =>
  new Promise((resolve) => {
    setTimeout(resolve, duration);
  });

