export const normalizeAccents = (input) => {
  return input
    .split("")
    .map((char) => accentsMap[char] || char)
    .join("");
};

/**
 * For formatting conditional class names
 *
 * @param {Record<string, boolean>} classNames
 * @returns {string}
 */
export const cn = (classNames) =>
  Object.entries(classNames)
    .filter(([, value]) => value)
    .map(([key]) => key)
    .join(" ");

/**
 * Returns a deep clone of the given object.
 *
 * XXX This could be made more efficient by avoiding conversion to JSON.
 */
export const deepClone = (object) => JSON.parse(JSON.stringify(object));

export const mulberry32 = (seed) => {
  return function () {
    let t = (seed += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

/** Splits the given `input` text into an array of sentences */
const splitIntoSentences = (input) => {
  const parts = input.split(/([.!?])\s+/);
  const sentences = [];

  for (let i = 0; i < parts.length; i += 2) {
    const sentence = parts[i] + (parts[i + 1] || "");
    sentences.push(sentence.trim());
  }

  return sentences;
};

/**
 * Returns the first sentence in the text that contains the word or phrase.
 */
export const findContextSentence = (text, wordOrPhrase) => {
  const sentences = splitIntoSentences(text);
  const regex = new RegExp(
    `(^|${notLetter})${regexpEscape(wordOrPhrase)}(?=${notLetter}|$)`,
    "iu"
  );

  for (const sentence of sentences) {
    if (regex.test(sentence)) {
      return sentence.trim();
    }
  }

  // Perhaps the word or phrase contains a sentence boundary character
  // (e.g., a period). So look for it in the entire text and if found, return the sentences either
  // side of the word or phrase.
  const match = text.match(regex);
  if (match) {
    const before = text.slice(0, match.index);
    const after = text.slice(match.index + match[0].length);

    const sentenceBefore = trimStart(splitIntoSentences(before).pop());
    const sentenceAfter = trimEnd(splitIntoSentences(after).shift());

    return sentenceBefore + match[0] + sentenceAfter;
  }

  return null;
};

/** Replacement for String.trimStart() but compatible with older browsers */
export const trimStart = (string) => string.replace(/^\s+/, "");

/** Replacement for String.trimEnd() but compatible with older browsers */
export const trimEnd = (string) => string.replace(/\s+$/, "");

export const filterOutEmojis = (text) =>
  text.replace(
    // eslint-disable-next-line no-misleading-character-class
    /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F700}-\u{1F77F}\u{1F780}-\u{1F7FF}\u{1F800}-\u{1F8FF}\u{1F900}-\u{1F9FF}\u{1FA00}-\u{1FA6F}\u{1FA70}-\u{1FAFF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{1F1E6}-\u{1F1FF}\u{1F191}-\u{1F251}\u{1F004}\u{1F0CF}\u{1F018}-\u{1F270}\u{238C}-\u{2454}\u{20D0}-\u{20FF}]/gu,
    ""
  );

/**
 * Returns "a" or "an" depending on the given number.
 */
export const aOrAn = (numeral) => {
  // Convert number to string to check the first digit/character
  const numStr = String(numeral);

  // Numbers that start with vowel sounds when spoken
  // 8 (eight), 11 (eleven), 18 (eighteen), etc.
  const vowelSoundStarters = [
    "8",
    "11",
    "18",
    "80",
    "81",
    "82",
    "83",
    "84",
    "85",
    "86",
    "87",
    "88",
    "89",
  ];

  // Check if the number starts with a vowel sound
  if (vowelSoundStarters.some((starter) => numStr.startsWith(starter))) {
    return "an";
  }

  return "a";
};
